import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  const [showProfile, setShowProfile] = useState(false);
  const [showTheme, setShowTheme] = useState(false);

  const [profile, setProfile] = useState({
    name: "User",
    email: "user@email.com"
  });

  useEffect(() => {
    const savedProfile = JSON.parse(localStorage.getItem("profile"));
    if (savedProfile) setProfile(savedProfile);
  }, []);

  const detectSource = (transactions) => {
    if (!transactions || transactions.length === 0) return "Not uploaded";

    const text = transactions
      .map((t) => t.description?.toLowerCase() || "")
      .join(" ");

    if (text.includes("gpay") || text.includes("upi")) return "GPay";
    if (text.includes("hdfc")) return "HDFC Bank";
    if (text.includes("sbi")) return "SBI Bank";

    return "Bank Statement";
  };

  const handleUpload = async () => {
    if (!file) return alert("Please select a PDF file");

    setLoading(true);

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://localhost:8000/upload-statement/", {
      method: "POST",
      body: formData,
    });

    const data = await res.json();

    setTransactions(data.transactions || []);
    setType(detectSource(data.transactions));

    const history = JSON.parse(localStorage.getItem("history")) || [];

    history.unshift({
      date: new Date().toLocaleString(),
      type: detectSource(data.transactions),
      count: data.transactions?.length || 0,
      transactions: data.transactions || []
    });

    localStorage.setItem("history", JSON.stringify(history));

    setLoading(false);
  };

  const deleteHistory = (index) => {
    const history = JSON.parse(localStorage.getItem("history")) || [];
    history.splice(index, 1);
    localStorage.setItem("history", JSON.stringify(history));
    setActiveTab("history");
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div>
            <div className="logo">FinSight</div>
            <div style={{ fontSize: "13px", color: "#6b7280" }}>
              Personal Expense Intelligence
            </div>
          </div>

          <div className="nav-actions">

            {/* TABS */}
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "history" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("history")}
              >
                History
              </span>
            </div>

            {/* PROFILE ICON */}
            <div
              onClick={() => {
                setShowProfile(!showProfile);
                setShowTheme(false);
              }}
              style={{
                width: "40px",
                height: "40px",
                borderRadius: "50%",
                background: "linear-gradient(135deg, #4f6df5, #6a85ff)",
                color: "white",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontWeight: "600",
                cursor: "pointer",
                marginLeft: "15px"
              }}
            >
              {profile.name.charAt(0).toUpperCase()}
            </div>

            {/* THEME BUTTON (NEW DESIGN) */}
            <div
              onClick={() => {
                setShowTheme(!showTheme);
                setShowProfile(false);
              }}
              style={{
                width: "36px",
                height: "36px",
                borderRadius: "50%",
                background: darkMode
                  ? "#111827"
                  : "#e5e7eb",
                cursor: "pointer",
                marginLeft: "15px",
                border: "1px solid #ccc"
              }}
            ></div>

          </div>
        </div>

        {/* THEME DROPDOWN */}
        {showTheme && (
          <div
            style={{
              position: "absolute",
              top: "75px",
              right: "30px",
              width: "180px",
              background: "#111",
              color: "white",
              borderRadius: "16px",
              padding: "10px",
              boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
              zIndex: 1000
            }}
          >
            <div
              onClick={() => {
                setDarkMode(false);
                setShowTheme(false);
              }}
              style={{
                display: "flex",
                alignItems: "center",
                padding: "10px",
                cursor: "pointer",
                borderRadius: "10px"
              }}
            >
              ☀️ <span style={{ marginLeft: "10px" }}>Light</span>
            </div>

            <div
              onClick={() => {
                setDarkMode(true);
                setShowTheme(false);
              }}
              style={{
                display: "flex",
                alignItems: "center",
                padding: "10px",
                cursor: "pointer",
                borderRadius: "10px"
              }}
            >
              🌙 <span style={{ marginLeft: "10px" }}>Dark</span>
            </div>
          </div>
        )}

        {/* PROFILE DROPDOWN */}
        {showProfile && (
          <div
            style={{
              position: "absolute",
              top: "75px",
              right: "80px",
              width: "260px",
              background: "white",
              borderRadius: "16px",
              boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
              padding: "20px",
              zIndex: 1000
            }}
          >
            <div style={{ marginBottom: "10px", fontWeight: "600" }}>
              {profile.name}
            </div>

            <input
              value={profile.name}
              onChange={(e) =>
                setProfile({ ...profile, name: e.target.value })
              }
              placeholder="Name"
            />

            <input
              value={profile.email}
              onChange={(e) =>
                setProfile({ ...profile, email: e.target.value })
              }
              placeholder="Email"
              style={{ marginTop: "10px" }}
            />

            <button
              style={{ marginTop: "15px" }}
              onClick={() => {
                localStorage.setItem("profile", JSON.stringify(profile));
                setShowProfile(false);
              }}
            >
              Save
            </button>
          </div>
        )}

        {/* HERO */}
        <div className="hero">
          <h1>
            Welcome, <span style={{ color: "#4f6df5" }}>{profile.name}</span>
          </h1>
        </div>

      </div>
    </div>
  );
}

export default Dashboard;
